namespace HRMS.Application.Services;

public sealed class PayrollInputService(IHrmsDbContext db, ITenantContext tenant, TimeProvider clock, IPayrollApprovalGuard? approvalGuard = null) : IPayrollInputService
{
    public async Task<Result<PagedResult<PayrollInputTemplateDto>>> GetTemplatesAsync(CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PagedResult<PayrollInputTemplateDto>>.Unauthorized("No authenticated tenant.");
        var rows = await db.PayrollInputTemplates.AsNoTracking().Include(x => x.Columns).Where(x => x.TenantId == tid).OrderBy(x => x.Code).ThenByDescending(x => x.Version).ToListAsync(ct);
        return Result<PagedResult<PayrollInputTemplateDto>>.Success(new(rows.Select(ToDto).ToList(), 1, rows.Count == 0 ? 25 : rows.Count, rows.Count));
    }

    public async Task<Result<PayrollInputTemplateDto>> CreateTemplateAsync(PayrollInputTemplateRequest request, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollInputTemplateDto>.Unauthorized("No authenticated tenant.");
        var code = request.Code.Trim().ToUpperInvariant();
        if (string.IsNullOrWhiteSpace(code) || string.IsNullOrWhiteSpace(request.Name)) return Result<PayrollInputTemplateDto>.Invalid("code", "Template code and name are required.");
        if (request.Columns.Count == 0) return Result<PayrollInputTemplateDto>.Invalid("columns", "At least one column mapping is required.");
        if (await db.PayrollInputTemplates.AnyAsync(x => x.TenantId == tid && x.Code == code && x.Version == 1, ct)) return Result<PayrollInputTemplateDto>.Conflict("A template with this code already exists.");
        var item = new PayrollInputTemplate { Id = Guid.NewGuid(), TenantId = tid, Code = code, Name = request.Name.Trim(), Description = request.Description?.Trim(), InputType = request.InputType, Active = request.Active, DateFormat = request.DateFormat.Trim() };
        item.Columns = request.Columns.Select(x => new PayrollInputTemplateColumn { Id = Guid.NewGuid(), TenantId = tid, TemplateId = item.Id, SourceColumnName = x.SourceColumnName.Trim(), TargetField = x.TargetField.Trim(), Required = x.Required, Position = x.Position, DefaultValue = x.DefaultValue, TransformType = x.TransformType }).ToList();
        db.PayrollInputTemplates.Add(item); await db.SaveChangesAsync(ct); return Result<PayrollInputTemplateDto>.Success(ToDto(item), "Template created.");
    }

    public async Task<Result<PayrollInputTemplateDto>> UpdateTemplateAsync(Guid id, PayrollInputTemplateRequest request, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollInputTemplateDto>.Unauthorized("No authenticated tenant.");
        var item = await db.PayrollInputTemplates.Include(x => x.Columns).FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == id, ct);
        if (item is null) return Result<PayrollInputTemplateDto>.NotFound("Template not found.");
        if (await db.PayrollInputBatches.AnyAsync(x => x.TenantId == tid && x.TemplateId == id && x.Status != PayrollInputBatchStatus.Draft, ct))
        {
            item = new PayrollInputTemplate { Id = Guid.NewGuid(), TenantId = tid, Code = item.Code, Version = item.Version + 1 };
            db.PayrollInputTemplates.Add(item);
        }
        item.Name = request.Name.Trim(); item.Description = request.Description?.Trim(); item.InputType = request.InputType; item.Active = request.Active; item.DateFormat = request.DateFormat.Trim(); item.ConcurrencyVersion++;
        item.Columns.Clear(); foreach (var column in request.Columns) item.Columns.Add(new PayrollInputTemplateColumn { Id = Guid.NewGuid(), TenantId = tid, TemplateId = item.Id, SourceColumnName = column.SourceColumnName.Trim(), TargetField = column.TargetField.Trim(), Required = column.Required, Position = column.Position, DefaultValue = column.DefaultValue, TransformType = column.TransformType, Active = true });
        await db.SaveChangesAsync(ct); return Result<PayrollInputTemplateDto>.Success(ToDto(item), "Template updated.");
    }

    public async Task<Result<PagedResult<PayrollInputBatchDto>>> GetBatchesAsync(PayrollInputBatchQuery query, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PagedResult<PayrollInputBatchDto>>.Unauthorized("No authenticated tenant.");
        var source = db.PayrollInputBatches.AsNoTracking().Where(x => x.TenantId == tid); if (query.Status is { } s) source = source.Where(x => x.Status == s); if (query.PayrollPeriodId is { } p) source = source.Where(x => x.PayrollPeriodId == p);
        return Result<PagedResult<PayrollInputBatchDto>>.Success(await source.OrderByDescending(x => x.CreatedDate).ThenBy(x => x.Id).Select(x => new PayrollInputBatchDto(x.Id, x.BatchNumber, x.Name, x.PayrollPeriodId, x.EffectiveDate, x.SourceType, x.Status, x.TotalRows, x.ValidRows, x.InvalidRows, x.WarningRows, x.TotalAmount, x.FileName)).ToPagedResultAsync(query, ct));
    }

    public async Task<Result<PayrollInputBatchDto>> CreateBatchAsync(PayrollInputBatchRequest request, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollInputBatchDto>.Unauthorized("No authenticated tenant.");
        if (string.IsNullOrWhiteSpace(request.Name)) return Result<PayrollInputBatchDto>.Invalid("name", "Batch name is required.");
        if (request.PayrollPeriodId is { } pid && !await db.PayrollPeriods.AnyAsync(x => x.TenantId == tid && x.Id == pid, ct)) return Result<PayrollInputBatchDto>.Invalid("payrollPeriodId", "Payroll period was not found.");
        if (request.TemplateId is { } templateId && !await db.PayrollInputTemplates.AnyAsync(x => x.TenantId == tid && x.Id == templateId && x.Active, ct)) return Result<PayrollInputBatchDto>.Invalid("templateId", "An active import template is required.");
        var batch = new PayrollInputBatch { Id = Guid.NewGuid(), TenantId = tid, BatchNumber = $"PIN/{clock.GetUtcNow():yyyyMMddHHmmss}/{Guid.NewGuid():N}"[..34], Name = request.Name.Trim(), Description = request.Description?.Trim(), PayrollPeriodId = request.PayrollPeriodId, EffectiveDate = request.EffectiveDate, SourceType = request.SourceType, TemplateId = request.TemplateId, CreatedByUserId = tenant.UserId };
        db.PayrollInputBatches.Add(batch); AddHistory(batch, PayrollInputHistoryEvent.Created, null, batch.Status, "Batch created.");
        foreach (var line in request.Lines.Select((x, i) => MapLine(tid, batch.Id, i + 1, x))) db.PayrollInputLines.Add(line);
        batch.TotalRows = request.Lines.Count; await db.SaveChangesAsync(ct); return Result<PayrollInputBatchDto>.Success(ToDto(batch), "Batch created.");
    }

    public async Task<Result<PayrollInputBatchDto>> UploadAsync(Guid batchId, Stream content, string fileName, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollInputBatchDto>.Unauthorized("No authenticated tenant.");
        var batch = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == batchId, ct); if (batch is null) return Result<PayrollInputBatchDto>.NotFound("Batch not found.");
        if (batch.Status != PayrollInputBatchStatus.Draft) return Result<PayrollInputBatchDto>.Conflict("Only draft batches can receive an upload.");
        if (content.Length == 0 || content.Length > 25 * 1024 * 1024) return Result<PayrollInputBatchDto>.Invalid("file", "The CSV must be non-empty and no larger than 25 MB.");
        var hash = Convert.ToHexString(SHA256.HashData(content)); content.Position = 0; if (batch.FileHash == hash) return Result<PayrollInputBatchDto>.Success(ToDto(batch), "This file is already staged for the batch."); if (await db.PayrollInputBatches.AnyAsync(x => x.TenantId == tid && x.FileHash == hash && x.Id != batchId, ct)) return Result<PayrollInputBatchDto>.Conflict("This file has already been imported for this tenant.");
        var rows = await ParseCsvAsync(content, batch, ct); if (!rows.Succeeded) return Result<PayrollInputBatchDto>.Failure(rows.Status, rows.Message, rows.Errors);
        await db.PayrollInputLines.Where(x => x.TenantId == tid && x.BatchId == batchId).ExecuteDeleteAsync(ct); db.PayrollInputLines.AddRange(rows.Value!); batch.FileName = Path.GetFileName(fileName); batch.FileHash = hash; batch.TotalRows = rows.Value!.Count; batch.ConcurrencyVersion++; AddHistory(batch, PayrollInputHistoryEvent.Uploaded, batch.Status, batch.Status, "CSV staged."); try { await db.SaveChangesAsync(ct); } catch (DbUpdateException) { return Result<PayrollInputBatchDto>.Conflict("This file was imported concurrently; retry is safe and will not duplicate the import."); } return Result<PayrollInputBatchDto>.Success(ToDto(batch), "CSV staged.");
    }

    public async Task<Result<PayrollInputBatchDto>> ValidateAsync(Guid batchId, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollInputBatchDto>.Unauthorized("No authenticated tenant.");
        var batch = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == batchId, ct); if (batch is null) return Result<PayrollInputBatchDto>.NotFound("Batch not found.");
        if (batch.Status is not (PayrollInputBatchStatus.Draft or PayrollInputBatchStatus.ValidationFailed or PayrollInputBatchStatus.Validated)) return Result<PayrollInputBatchDto>.Conflict("The batch is not editable or validatable in its current state.");
        db.PayrollInputValidationIssues.RemoveRange(db.PayrollInputValidationIssues.Where(x => x.TenantId == tid && x.BatchId == batchId));
        var lines = await db.PayrollInputLines.Where(x => x.TenantId == tid && x.BatchId == batchId).OrderBy(x => x.RowNumber).ToListAsync(ct); var employees = await db.Employees.Where(x => x.TenantId == tid && x.EmployeeCode != null).ToDictionaryAsync(x => x.EmployeeCode!.ToUpper(), ct); var components = await db.SalaryComponents.Where(x => x.TenantId == tid).ToDictionaryAsync(x => x.Code.ToUpper(), ct);
        foreach (var line in lines) { line.Status = PayrollInputLineStatus.Valid; line.ValidationMessage = null; var issues = new List<PayrollInputValidationIssue>(); var code = line.EmployeeCodeSnapshot.Trim().ToUpperInvariant(); if (!employees.TryGetValue(code, out var employee)) issues.Add(Issue(batch, line, PayrollInputIssueSeverity.Error, "EMPLOYEE_NOT_FOUND", "employeeCode", "Employee was not found in this tenant.")); else { line.EmployeeId = employee.Id; if (employee.Status != EmployeeStatus.Active) issues.Add(Issue(batch, line, PayrollInputIssueSeverity.Warning, "EMPLOYEE_INACTIVE", "employeeCode", "Employee is inactive.")); } var componentCode = line.ComponentCodeSnapshot.Trim().ToUpperInvariant(); if (!components.TryGetValue(componentCode, out var component)) issues.Add(Issue(batch, line, PayrollInputIssueSeverity.Error, "COMPONENT_NOT_FOUND", "componentCode", "Salary component was not found in this tenant.")); else { line.SalaryComponentId = component.Id; if (!component.IsActive || line.EffectiveDate < component.EffectiveFrom || component.EffectiveTo < line.EffectiveDate) issues.Add(Issue(batch, line, PayrollInputIssueSeverity.Error, "COMPONENT_NOT_EFFECTIVE", "componentCode", "Salary component is not active/effective for this input date.")); var expected = line.InputType is PayrollInputType.OneTimeDeduction or PayrollInputType.RecoveryInput ? SalaryComponentType.Deduction : SalaryComponentType.Earning; if (line.InputType != PayrollInputType.InformationOnly && component.ComponentType != expected) issues.Add(Issue(batch, line, PayrollInputIssueSeverity.Error, "INVALID_COMPONENT_TYPE", "componentCode", "Component behavior does not match the input type.")); }
            if (line.Amount is null || line.Amount <= 0) issues.Add(Issue(batch, line, PayrollInputIssueSeverity.Error, "INVALID_AMOUNT", "amount", "Amount must be greater than zero.")); var targetPeriodId = line.PayrollPeriodId ?? batch.PayrollPeriodId; if (targetPeriodId is { } pid && await db.PayrollPeriods.AnyAsync(x => x.TenantId == tid && x.Id == pid && (x.Status == PayrollPeriodStatus.Closed || x.Status == PayrollPeriodStatus.Locked), ct)) issues.Add(Issue(batch, line, PayrollInputIssueSeverity.Error, "PERIOD_FINALIZED", "payrollPeriodId", "Finalized payroll cannot be rewritten; use Phase 7R correction workflow."));
            var duplicate = lines.Any(x => x.Id != line.Id && x.EmployeeCodeSnapshot == line.EmployeeCodeSnapshot && x.ComponentCodeSnapshot == line.ComponentCodeSnapshot && x.EffectiveDate == line.EffectiveDate && x.ReferenceNumber == line.ReferenceNumber && x.Amount == line.Amount); if (duplicate) issues.Add(Issue(batch, line, PayrollInputIssueSeverity.Error, "DUPLICATE_ROW", null, "Duplicate logical input row."));
            foreach (var issue in issues) db.PayrollInputValidationIssues.Add(issue); if (issues.Any(x => x.Severity == PayrollInputIssueSeverity.Error)) line.Status = PayrollInputLineStatus.Invalid; else if (issues.Count > 0) line.Status = PayrollInputLineStatus.Warning; line.ValidationMessage = string.Join("; ", issues.Select(x => x.Message));
        }
        batch.TotalRows = lines.Count; batch.ValidRows = lines.Count(x => x.Status is PayrollInputLineStatus.Valid or PayrollInputLineStatus.Warning); batch.InvalidRows = lines.Count(x => x.Status == PayrollInputLineStatus.Invalid); batch.WarningRows = lines.Count(x => x.Status == PayrollInputLineStatus.Warning); batch.TotalAmount = lines.Where(x => x.Amount.HasValue).Sum(x => x.Amount!.Value); batch.Status = batch.InvalidRows > 0 ? PayrollInputBatchStatus.ValidationFailed : PayrollInputBatchStatus.Validated; batch.ConcurrencyVersion++; AddHistory(batch, batch.InvalidRows > 0 ? PayrollInputHistoryEvent.ValidationFailed : PayrollInputHistoryEvent.Validated, null, batch.Status, "Batch validation completed."); try { await db.SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { return Result<PayrollInputBatchDto>.Conflict("The batch changed while validation was in progress; retry validation."); } return Result<PayrollInputBatchDto>.Success(ToDto(batch));
    }

    public async Task<Result<PayrollInputPreviewDto>> GetPreviewAsync(Guid batchId, CancellationToken ct = default)
    { var batch = await GetBatchAsync(batchId, ct); if (!batch.Succeeded) return Result<PayrollInputPreviewDto>.Failure(batch.Status, batch.Message, batch.Errors); var lines = db.PayrollInputLines.AsNoTracking().Where(x => x.TenantId == batch.Value!.TenantId && x.BatchId == batchId); var earning = await lines.Where(x => (x.InputType == PayrollInputType.OneTimeEarning || x.InputType == PayrollInputType.ArrearInput) && x.Status != PayrollInputLineStatus.Invalid).SumAsync(x => x.Amount ?? 0, ct); var deduction = await lines.Where(x => (x.InputType == PayrollInputType.OneTimeDeduction || x.InputType == PayrollInputType.RecoveryInput) && x.Status != PayrollInputLineStatus.Invalid).SumAsync(x => x.Amount ?? 0, ct); var employees = await lines.Where(x => x.EmployeeId.HasValue).Select(x => x.EmployeeId!.Value).Distinct().CountAsync(ct); var components = await lines.Where(x => x.SalaryComponentId.HasValue).Select(x => x.SalaryComponentId!.Value).Distinct().CountAsync(ct); return Result<PayrollInputPreviewDto>.Success(new(ToDto(batch.Value!), employees, components, earning, deduction, earning - deduction)); }

    public async Task<Result<PayrollInputLineDto>> UpdateLineAsync(Guid batchId, Guid lineId, PayrollInputLineUpdateRequest request, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollInputLineDto>.Unauthorized("No authenticated tenant.");
        var batch = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == batchId, ct); var line = await db.PayrollInputLines.FirstOrDefaultAsync(x => x.TenantId == tid && x.BatchId == batchId && x.Id == lineId, ct);
        if (batch is null || line is null) return Result<PayrollInputLineDto>.NotFound("Staged input line was not found.");
        if (batch.Status is not (PayrollInputBatchStatus.Draft or PayrollInputBatchStatus.ValidationFailed or PayrollInputBatchStatus.Validated)) return Result<PayrollInputLineDto>.Conflict("Only editable batches can be corrected.");
        db.PayrollInputValidationIssues.RemoveRange(db.PayrollInputValidationIssues.Where(x => x.TenantId == tid && x.LineId == lineId));
        line.EmployeeCodeSnapshot = request.EmployeeCode.Trim(); line.ComponentCodeSnapshot = request.ComponentCode.Trim(); line.InputType = request.InputType; line.Amount = request.Amount; line.Quantity = request.Quantity; line.Rate = request.Rate; line.EffectiveDate = request.EffectiveDate; line.PayrollPeriodId = request.PayrollPeriodId ?? batch.PayrollPeriodId; line.ReferenceNumber = request.ReferenceNumber?.Trim(); line.Remarks = request.Remarks?.Trim(); line.EmployeeId = null; line.SalaryComponentId = null; line.Status = PayrollInputLineStatus.Staged; line.ValidationMessage = "Revalidation required."; line.SourceRowHash = Hash($"{line.EmployeeCodeSnapshot}|{line.ComponentCodeSnapshot}|{line.InputType}|{line.Amount}|{line.EffectiveDate}|{line.ReferenceNumber}"); batch.Status = PayrollInputBatchStatus.Draft; batch.ValidRows = 0; batch.InvalidRows = 0; batch.WarningRows = 0; batch.ConcurrencyVersion++; line.ConcurrencyVersion++; AddHistory(batch, PayrollInputHistoryEvent.Corrected, PayrollInputBatchStatus.Validated, batch.Status, $"Line {line.RowNumber} corrected."); try { await db.SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { return Result<PayrollInputLineDto>.Conflict("The staged line changed while correction was in progress; reload and retry."); } return Result<PayrollInputLineDto>.Success(ToLineDto(line));
    }

    public async Task<Result<bool>> DeleteLineAsync(Guid batchId, Guid lineId, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<bool>.Unauthorized("No authenticated tenant.");
        var batch = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == batchId, ct); var line = await db.PayrollInputLines.FirstOrDefaultAsync(x => x.TenantId == tid && x.BatchId == batchId && x.Id == lineId, ct);
        if (batch is null || line is null) return Result<bool>.NotFound("Staged input line was not found.");
        if (batch.Status is not (PayrollInputBatchStatus.Draft or PayrollInputBatchStatus.ValidationFailed or PayrollInputBatchStatus.Validated)) return Result<bool>.Conflict("Only editable batches can have rows deleted.");
        db.PayrollInputValidationIssues.RemoveRange(db.PayrollInputValidationIssues.Where(x => x.TenantId == tid && x.LineId == lineId)); db.PayrollInputLines.Remove(line); batch.Status = PayrollInputBatchStatus.Draft; batch.TotalRows = Math.Max(0, batch.TotalRows - 1); batch.ValidRows = 0; batch.InvalidRows = 0; batch.WarningRows = 0; batch.ConcurrencyVersion++; AddHistory(batch, PayrollInputHistoryEvent.Corrected, PayrollInputBatchStatus.Validated, batch.Status, $"Line {line.RowNumber} deleted."); await db.SaveChangesAsync(ct); return Result<bool>.Success(true, "Line deleted.");
    }

    public async Task<Result<PagedResult<PayrollInputLineDto>>> GetLinesAsync(Guid batchId, int page, int pageSize, PayrollInputLineStatus? status, CancellationToken ct = default) { var tid = tenant.TenantId; if (tid is null) return Result<PagedResult<PayrollInputLineDto>>.Unauthorized("No authenticated tenant."); page = Math.Max(1, page); pageSize = Math.Clamp(pageSize, 1, 200); var q = db.PayrollInputLines.AsNoTracking().Where(x => x.TenantId == tid && x.BatchId == batchId); if (status is { } s) q = q.Where(x => x.Status == s); var total = await q.CountAsync(ct); var items = await q.OrderBy(x => x.RowNumber).ThenBy(x => x.Id).Skip((page - 1) * pageSize).Take(pageSize).Select(x => new PayrollInputLineDto(x.Id, x.RowNumber, x.EmployeeCodeSnapshot, x.ComponentCodeSnapshot, x.InputType, x.Amount, x.EffectiveDate, x.Status, x.ValidationMessage)).ToListAsync(ct); return Result<PagedResult<PayrollInputLineDto>>.Success(new(items, page, pageSize, total)); }
    public async Task<Result<PagedResult<PayrollInputIssueDto>>> GetIssuesAsync(Guid batchId, int page, int pageSize, PayrollInputIssueSeverity? severity, CancellationToken ct = default) { var tid = tenant.TenantId; if (tid is null) return Result<PagedResult<PayrollInputIssueDto>>.Unauthorized("No authenticated tenant."); page = Math.Max(1, page); pageSize = Math.Clamp(pageSize, 1, 200); var q = db.PayrollInputValidationIssues.AsNoTracking().Where(x => x.TenantId == tid && x.BatchId == batchId); if (severity is { } s) q = q.Where(x => x.Severity == s); var total = await q.CountAsync(ct); var items = await q.OrderBy(x => x.RowNumber).ThenBy(x => x.Id).Skip((page - 1) * pageSize).Take(pageSize).Select(x => new PayrollInputIssueDto(x.Id, x.LineId, x.RowNumber, x.Severity, x.Code, x.FieldName, x.Message)).ToListAsync(ct); return Result<PagedResult<PayrollInputIssueDto>>.Success(new(items, page, pageSize, total)); }

    public Task<Result<PayrollInputBatchDto>> SubmitAsync(Guid id, CancellationToken ct = default) => TransitionAsync(id, PayrollInputBatchStatus.Submitted, PayrollInputHistoryEvent.Submitted, PayrollInputBatchStatus.Validated, null, ct);
    public async Task<Result<PayrollInputBatchDto>> ApproveAsync(Guid id, CancellationToken ct = default) { var batch = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tenant.TenantId && x.Id == id, ct); if (batch is null) return Result<PayrollInputBatchDto>.NotFound("Batch not found."); if (batch.Status != PayrollInputBatchStatus.Submitted) return Result<PayrollInputBatchDto>.Conflict("Only submitted batches can be approved."); var guard = await (approvalGuard ?? new PayrollApprovalGuard(db, tenant)).ValidateAsync(batch.SubmittedByUserId, "approve", ct: ct); if (!guard.Succeeded) return Result<PayrollInputBatchDto>.Failure(guard.Status, guard.Message, guard.Errors); return await TransitionAsync(id, PayrollInputBatchStatus.Approved, PayrollInputHistoryEvent.Approved, PayrollInputBatchStatus.Submitted, null, ct); }
    public Task<Result<PayrollInputBatchDto>> RejectAsync(Guid id, string reason, CancellationToken ct = default) => TransitionAsync(id, PayrollInputBatchStatus.Rejected, PayrollInputHistoryEvent.Rejected, PayrollInputBatchStatus.Submitted, reason, ct);
    public async Task<Result<PayrollInputBatchDto>> PostAsync(Guid id, CancellationToken ct = default) { if (tenant.TenantId is not Guid tid) return Result<PayrollInputBatchDto>.Unauthorized("No authenticated tenant."); await using var transaction = await db.BeginTransactionAsync(IsolationLevel.Serializable, ct); var batch = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == id, ct); if (batch is null) return Result<PayrollInputBatchDto>.NotFound("Batch not found."); if (batch.Status == PayrollInputBatchStatus.Posted) { await transaction.CommitAsync(ct); return Result<PayrollInputBatchDto>.Success(ToDto(batch), "Batch was already posted."); } if (batch.Status != PayrollInputBatchStatus.Approved || batch.InvalidRows > 0) return Result<PayrollInputBatchDto>.Conflict("Only an approved, atomically valid batch can be posted."); var lines = await db.PayrollInputLines.Where(x => x.TenantId == tid && x.BatchId == id && x.Status != PayrollInputLineStatus.Invalid).ToListAsync(ct); foreach (var line in lines.Where(x => x.InputType != PayrollInputType.InformationOnly && x.Status != PayrollInputLineStatus.Posted)) { if (line.EmployeeId is not Guid employeeId || line.SalaryComponentId is not Guid componentId) return Result<PayrollInputBatchDto>.Conflict("Batch must be validated before posting."); if (await db.PayrollAdjustments.AnyAsync(x => x.TenantId == tid && x.SourceType == "PayrollInputBatch" && x.SourceId == line.Id, ct)) { line.Status = PayrollInputLineStatus.Posted; continue; } var deduction = line.InputType is PayrollInputType.OneTimeDeduction or PayrollInputType.RecoveryInput; db.PayrollAdjustments.Add(new PayrollAdjustment { Id = Guid.NewGuid(), TenantId = tid, EmployeeId = employeeId, SourceType = "PayrollInputBatch", SourceId = line.Id, SourceReferenceId = id, SalaryComponentId = componentId, ComponentCode = line.ComponentCodeSnapshot, AdjustmentNumber = $"PIN/{batch.BatchNumber}/{line.RowNumber}", AdjustmentType = deduction ? PayrollAdjustmentType.AdditionalDeduction : PayrollAdjustmentType.AdditionalEarning, Direction = deduction ? PayrollAdjustmentDirection.Deduction : PayrollAdjustmentDirection.Earning, Description = line.Remarks ?? $"Payroll input {batch.BatchNumber}", Amount = line.Amount!.Value, EffectiveDate = line.EffectiveDate, PayrollPeriodId = line.PayrollPeriodId ?? batch.PayrollPeriodId, Status = PayrollAdjustmentStatus.Approved, ApprovedByUserId = tenant.UserId, ApprovedAtUtc = clock.GetUtcNow().UtcDateTime }); line.Status = PayrollInputLineStatus.Posted; } batch.Status = PayrollInputBatchStatus.Posted; batch.PostedByUserId = tenant.UserId; batch.PostedAtUtc = clock.GetUtcNow().UtcDateTime; batch.ConcurrencyVersion++; AddHistory(batch, PayrollInputHistoryEvent.Posted, PayrollInputBatchStatus.Approved, batch.Status, "Approved inputs posted to Payroll adjustments."); try { await db.SaveChangesAsync(ct); await transaction.CommitAsync(ct); } catch (DbUpdateException) { await transaction.RollbackAsync(CancellationToken.None); return Result<PayrollInputBatchDto>.Conflict("This batch was posted concurrently; retry is safe and will not duplicate Payroll adjustments."); } return Result<PayrollInputBatchDto>.Success(ToDto(batch), "Batch posted."); }
    public async Task<Result<PayrollInputBatchDto>> CancelAsync(Guid id, string reason, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollInputBatchDto>.Unauthorized("No authenticated tenant.");
        var batch = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == id, ct);
        if (batch is null) return Result<PayrollInputBatchDto>.NotFound("Batch not found.");
        if (batch.Status == PayrollInputBatchStatus.Posted)
        {
            var applied = await db.PayrollAdjustmentApplications.AnyAsync(x => x.TenantId == tid && db.PayrollAdjustments.Any(a => a.TenantId == tid && a.SourceReferenceId == id && a.Id == x.PayrollAdjustmentId), ct);
            if (applied) return Result<PayrollInputBatchDto>.Conflict("Finalized Payroll may not be rewritten; submit this correction through Phase 7R.");
            await db.PayrollAdjustments.Where(x => x.TenantId == tid && x.SourceReferenceId == id && x.Status != PayrollAdjustmentStatus.Applied).ExecuteUpdateAsync(setters => setters.SetProperty(x => x.Status, PayrollAdjustmentStatus.Cancelled), ct);
        }
        if (batch.Status is not (PayrollInputBatchStatus.Draft or PayrollInputBatchStatus.Validated or PayrollInputBatchStatus.ValidationFailed or PayrollInputBatchStatus.Approved or PayrollInputBatchStatus.Posted)) return Result<PayrollInputBatchDto>.Conflict("The batch cannot be cancelled in its current state.");
        var old = batch.Status; batch.Status = PayrollInputBatchStatus.Cancelled; batch.CancelledAtUtc = clock.GetUtcNow().UtcDateTime; batch.CancelledByUserId = tenant.UserId; batch.CancellationReason = reason; batch.ConcurrencyVersion++; AddHistory(batch, PayrollInputHistoryEvent.Cancelled, old, batch.Status, reason);
        try { await db.SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { return Result<PayrollInputBatchDto>.Conflict("The batch changed while cancellation was in progress; reload and retry."); } return Result<PayrollInputBatchDto>.Success(ToDto(batch), "Batch cancelled.");
    }
    public async Task<Result<IReadOnlyList<PayrollInputHistoryDto>>> GetHistoryAsync(Guid id, CancellationToken ct = default) { if (tenant.TenantId is not Guid tid || !await db.PayrollInputBatches.AnyAsync(x => x.TenantId == tid && x.Id == id, ct)) return Result<IReadOnlyList<PayrollInputHistoryDto>>.NotFound("Batch not found."); var rows = await db.PayrollInputHistories.AsNoTracking().Where(x => x.TenantId == tid && x.BatchId == id).OrderBy(x => x.OccurredAtUtc).Select(x => new PayrollInputHistoryDto(x.Event, x.PreviousStatus, x.NewStatus, x.OccurredAtUtc, x.ActorUserId, x.Message)).ToListAsync(ct); return Result<IReadOnlyList<PayrollInputHistoryDto>>.Success(rows); }

    public async Task<Result<PayrollOutputFile>> ExportIssuesAsync(Guid batchId, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollOutputFile>.Unauthorized("No authenticated tenant.");
        if (!await db.PayrollInputBatches.AnyAsync(x => x.TenantId == tid && x.Id == batchId, ct)) return Result<PayrollOutputFile>.NotFound("Batch not found.");
        var rows = await db.PayrollInputValidationIssues.AsNoTracking().Where(x => x.TenantId == tid && x.BatchId == batchId).Join(db.PayrollInputLines, issue => new { issue.TenantId, LineId = issue.LineId!.Value }, line => new { line.TenantId, LineId = line.Id }, (issue, line) => new { issue, line }).OrderBy(x => x.issue.RowNumber).ToListAsync(ct);
        var csv = new CsvBuilder("RowNumber", "EmployeeCode", "ComponentCode", "Field", "Severity", "ErrorCode", "Message"); foreach (var row in rows) csv.AppendRow(row.issue.RowNumber?.ToString(), row.line.EmployeeCodeSnapshot, row.line.ComponentCodeSnapshot, row.issue.FieldName, row.issue.Severity.ToString(), row.issue.Code, row.issue.Message);
        return Result<PayrollOutputFile>.Success(new PayrollOutputFile($"payroll-input-issues-{batchId:N}.csv", "text/csv; charset=utf-8", csv.ToUtf8Bytes()));
    }

    public async Task<Result<PayrollOutputFile>> ExportPreviewAsync(Guid batchId, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollOutputFile>.Unauthorized("No authenticated tenant.");
        if (!await db.PayrollInputBatches.AnyAsync(x => x.TenantId == tid && x.Id == batchId, ct)) return Result<PayrollOutputFile>.NotFound("Batch not found.");
        var rows = await db.PayrollInputLines.AsNoTracking().Where(x => x.TenantId == tid && x.BatchId == batchId).Include(x => x.Employee).Include(x => x.SalaryComponent).OrderBy(x => x.RowNumber).ToListAsync(ct); var csv = new CsvBuilder("RowNumber", "EmployeeCode", "EmployeeName", "ComponentCode", "ComponentName", "InputType", "Amount", "EffectiveDate", "ValidationStatus", "ReferenceNumber", "Remarks"); foreach (var row in rows) csv.AppendRow(row.RowNumber.ToString(), row.EmployeeCodeSnapshot, row.Employee is null ? null : $"{row.Employee.FirstName} {row.Employee.LastName}".Trim(), row.ComponentCodeSnapshot, row.SalaryComponent?.Name, row.InputType.ToString(), row.Amount?.ToString(CultureInfo.InvariantCulture), row.EffectiveDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture), row.Status.ToString(), row.ReferenceNumber, row.Remarks); return Result<PayrollOutputFile>.Success(new PayrollOutputFile($"payroll-input-preview-{batchId:N}.csv", "text/csv; charset=utf-8", csv.ToUtf8Bytes()));
    }

    public async Task<Result<PayrollOutputFile>> ExportResultAsync(Guid batchId, CancellationToken ct = default)
    {
        if (tenant.TenantId is not Guid tid) return Result<PayrollOutputFile>.Unauthorized("No authenticated tenant."); var batch = await db.PayrollInputBatches.AsNoTracking().FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == batchId, ct); if (batch is null) return Result<PayrollOutputFile>.NotFound("Batch not found."); if (batch.Status != PayrollInputBatchStatus.Posted) return Result<PayrollOutputFile>.Conflict("Only posted batches have a result export."); var rows = await db.PayrollAdjustments.AsNoTracking().Where(x => x.TenantId == tid && x.SourceType == "PayrollInputBatch" && x.SourceReferenceId == batchId).Join(db.PayrollInputLines, adjustment => new { adjustment.TenantId, LineId = adjustment.SourceId }, line => new { line.TenantId, LineId = line.Id }, (adjustment, line) => new { adjustment, line }).Join(db.Employees, x => new { x.adjustment.TenantId, x.adjustment.EmployeeId }, employee => new { employee.TenantId, EmployeeId = employee.Id }, (x, employee) => new { x.adjustment, x.line, employee }).OrderBy(x => x.line.RowNumber).ToListAsync(ct); var csv = new CsvBuilder("RowNumber", "EmployeeCode", "ComponentCode", "Amount", "AdjustmentReference", "PostedAt", "Status"); foreach (var row in rows) csv.AppendRow(row.line.RowNumber.ToString(), row.employee.EmployeeCode, row.adjustment.ComponentCode, row.adjustment.Amount.ToString(CultureInfo.InvariantCulture), row.adjustment.AdjustmentNumber, row.adjustment.AppliedAtUtc?.ToString("O", CultureInfo.InvariantCulture), row.adjustment.Status.ToString()); return Result<PayrollOutputFile>.Success(new PayrollOutputFile($"payroll-input-result-{batchId:N}.csv", "text/csv; charset=utf-8", csv.ToUtf8Bytes()));
    }

    private async Task<Result<PayrollInputBatchDto>> TransitionAsync(Guid id, PayrollInputBatchStatus next, PayrollInputHistoryEvent ev, PayrollInputBatchStatus required, string? message, CancellationToken ct) { if (tenant.TenantId is not Guid tid) return Result<PayrollInputBatchDto>.Unauthorized("No authenticated tenant."); var b = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == id, ct); if (b is null) return Result<PayrollInputBatchDto>.NotFound("Batch not found."); if (b.Status != required) return Result<PayrollInputBatchDto>.Conflict("The batch transition is not allowed."); if (next == PayrollInputBatchStatus.Submitted && b.InvalidRows > 0) return Result<PayrollInputBatchDto>.Conflict("Invalid rows must be corrected before submission."); var old = b.Status; b.Status = next; if (next == PayrollInputBatchStatus.Submitted) { b.SubmittedAtUtc = clock.GetUtcNow().UtcDateTime; b.SubmittedByUserId = tenant.UserId; } if (next == PayrollInputBatchStatus.Cancelled) { b.CancelledAtUtc = clock.GetUtcNow().UtcDateTime; b.CancelledByUserId = tenant.UserId; b.CancellationReason = message; } b.ConcurrencyVersion++; AddHistory(b, ev, old, next, message); try { await db.SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException) { return Result<PayrollInputBatchDto>.Conflict("The batch changed while this command was in progress."); } return Result<PayrollInputBatchDto>.Success(ToDto(b)); }

    private async Task<Result<PayrollInputBatch>> GetBatchAsync(Guid id, CancellationToken ct) { if (tenant.TenantId is not Guid tid) return Result<PayrollInputBatch>.Unauthorized("No authenticated tenant."); var b = await db.PayrollInputBatches.FirstOrDefaultAsync(x => x.TenantId == tid && x.Id == id, ct); return b is null ? Result<PayrollInputBatch>.NotFound("Batch not found.") : Result<PayrollInputBatch>.Success(b); }
    private PayrollInputValidationIssue Issue(PayrollInputBatch b, PayrollInputLine l, PayrollInputIssueSeverity s, string code, string? field, string msg) => new() { Id = Guid.NewGuid(), TenantId = b.TenantId, BatchId = b.Id, LineId = l.Id, RowNumber = l.RowNumber, Severity = s, Code = code, FieldName = field, Message = msg };
    private void AddHistory(PayrollInputBatch b, PayrollInputHistoryEvent ev, PayrollInputBatchStatus? previous, PayrollInputBatchStatus? next, string? message) => db.PayrollInputHistories.Add(new PayrollInputHistory { Id = Guid.NewGuid(), TenantId = b.TenantId, BatchId = b.Id, Event = ev, PreviousStatus = previous, NewStatus = next, ActorUserId = tenant.UserId, OccurredAtUtc = clock.GetUtcNow().UtcDateTime, Message = message });
    private static PayrollInputLine MapLine(Guid tid, Guid bid, int row, PayrollInputLineRequest x) => new() { Id = Guid.NewGuid(), TenantId = tid, BatchId = bid, RowNumber = row, EmployeeCodeSnapshot = x.EmployeeCode.Trim(), ComponentCodeSnapshot = x.ComponentCode.Trim(), InputType = x.InputType, Amount = x.Amount, Quantity = x.Quantity, Rate = x.Rate, EffectiveDate = x.EffectiveDate, PayrollPeriodId = x.PayrollPeriodId, ReferenceNumber = x.ReferenceNumber?.Trim(), Remarks = x.Remarks?.Trim(), SourceRowHash = Hash($"{x.EmployeeCode}|{x.ComponentCode}|{x.InputType}|{x.Amount}|{x.EffectiveDate}|{x.ReferenceNumber}") };
    private static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
    private static PayrollInputBatchDto ToDto(PayrollInputBatch x) => new(x.Id, x.BatchNumber, x.Name, x.PayrollPeriodId, x.EffectiveDate, x.SourceType, x.Status, x.TotalRows, x.ValidRows, x.InvalidRows, x.WarningRows, x.TotalAmount, x.FileName);
    private static PayrollInputLineDto ToLineDto(PayrollInputLine x) => new(x.Id, x.RowNumber, x.EmployeeCodeSnapshot, x.ComponentCodeSnapshot, x.InputType, x.Amount, x.EffectiveDate, x.Status, x.ValidationMessage);
    private static PayrollInputTemplateDto ToDto(PayrollInputTemplate x) => new(x.Id, x.Code, x.Name, x.Description, x.InputType, x.Active, x.Version, x.Columns.OrderBy(c => c.Position).Select(c => new PayrollInputTemplateColumnDto(c.Id, c.SourceColumnName, c.TargetField, c.Required, c.Position, c.DefaultValue, c.TransformType)).ToList());

    private static async Task<Result<List<PayrollInputLine>>> ParseCsvAsync(Stream stream, PayrollInputBatch batch, CancellationToken ct)
    {
        using var reader = new StreamReader(stream, new UTF8Encoding(false, true), true, 64 * 1024, leaveOpen: true); var header = await reader.ReadLineAsync(ct); if (string.IsNullOrWhiteSpace(header)) return Result<List<PayrollInputLine>>.Invalid("file", "CSV header is missing."); var headers = ParseCsvRow(header); if (headers.Count != headers.Distinct(StringComparer.OrdinalIgnoreCase).Count()) return Result<List<PayrollInputLine>>.Invalid("file", "CSV contains duplicate headers."); var map = headers.Select((x, i) => (Name: x.Trim(), Index: i)).ToDictionary(x => x.Name, x => x.Index, StringComparer.OrdinalIgnoreCase); var required = new[] { "EmployeeCode", "ComponentCode", "Amount", "EffectiveDate" }; if (required.Any(x => !map.ContainsKey(x))) return Result<List<PayrollInputLine>>.Invalid("file", "CSV is missing one or more required headers."); var rows = new List<PayrollInputLine>(); var rowNo = 1; string? raw; try { while ((raw = await reader.ReadLineAsync(ct)) is not null) { rowNo++; if (string.IsNullOrWhiteSpace(raw)) continue; var fields = ParseCsvRow(raw); string Get(string n) => map.TryGetValue(n, out var i) && i < fields.Count ? fields[i].Trim() : string.Empty; var amount = decimal.TryParse(Get("Amount"), NumberStyles.Number, CultureInfo.InvariantCulture, out var a) ? a : (decimal?)null; var date = DateOnly.TryParse(Get("EffectiveDate"), CultureInfo.InvariantCulture, DateTimeStyles.None, out var d) ? d : batch.EffectiveDate; Enum.TryParse(Get("InputType"), true, out PayrollInputType type); var line = new PayrollInputLine { Id = Guid.NewGuid(), TenantId = batch.TenantId, BatchId = batch.Id, RowNumber = rowNo, EmployeeCodeSnapshot = Get("EmployeeCode"), ComponentCodeSnapshot = Get("ComponentCode"), InputType = type, Amount = amount, EffectiveDate = date, PayrollPeriodId = batch.PayrollPeriodId, ReferenceNumber = Get("ReferenceNumber"), Remarks = Get("Remarks"), SourceRowHash = Hash(raw) }; rows.Add(line); } } catch (DecoderFallbackException) { return Result<List<PayrollInputLine>>.Invalid("file", "CSV encoding is invalid."); } return Result<List<PayrollInputLine>>.Success(rows);
    }
    private static List<string> ParseCsvRow(string row) { var result = new List<string>(); var value = new StringBuilder(); var quoted = false; for (var i = 0; i < row.Length; i++) { var ch = row[i]; if (ch == '"') { if (quoted && i + 1 < row.Length && row[i + 1] == '"') { value.Append('"'); i++; } else quoted = !quoted; } else if (ch == ',' && !quoted) { result.Add(value.ToString()); value.Clear(); } else value.Append(ch); } result.Add(value.ToString()); return result; }
}
